<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import EChart from '../../components/EChart.vue'
import { getLayoutTemplates } from '../../api/assets.js'
import { getCommunities } from '../../api/community.js'
import { getRentalAgencies, getRentalDetail, getRentals, getRentalSummary } from '../../api/rental.js'
import { apiMessage } from '../../api/http.js'
import PaginationBar from '../../components/common/PaginationBar.vue'
const year = ref(2026), loading = ref(false), rows = ref([]), total = ref(0), summary = ref({}), communities = ref([]), agencies = ref([]), layouts = ref([]), detail = ref(null), drawer = ref(false), activeTab = ref('list')
const query = reactive({ communityId: null, agencyId: null, status: '', listingMode: '', layoutType: '', keyword: '', rentMin: null, rentMax: null, page: 1, pageSize: 20 })
const statusLabels = { PUBLISHED: '挂牌中', RENTED: '已出租', CLOSED: '已关闭', EXPIRED: '已过期' }, modeLabels = { SELF: '业主直租', AGENCY: '中介挂牌' }
const layoutNames = computed(() => Object.fromEntries(layouts.value.map(item => [item.layoutType, item.layoutName])))
const layoutName = row => row?.layoutName || layoutNames.value[row?.layoutType] || (row?.layoutType === '未填' ? '未填' : '户型未命名')
const money = v => new Intl.NumberFormat('zh-CN', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(v || 0)
const cards = computed(() => [['当前挂牌', summary.value.currentPublishedCount], ['本期已出租挂牌', summary.value.rentedInPeriodCount], ['业主直租', summary.value.selfCount], ['中介挂牌', summary.value.agencyCount], ['平均月租', `¥ ${money(summary.value.averageMonthlyRent)}`], ['平均挂牌天数', `${Number(summary.value.averageListingDays || 0).toFixed(1)} 天`]])
const pie = rows => ({ tooltip: { trigger: 'item' }, legend: { bottom: 0 }, series: [{ type: 'pie', radius: ['40%', '70%'], data: (rows || []).map(x => ({ name: modeLabels[x.label] || statusLabels[x.label] || layoutNames.value[x.label] || (x.label === '未填' ? '未填' : '户型未命名'), value: x.value })) }] })
const modeOption = computed(() => pie(summary.value.modeDistribution)), statusOption = computed(() => pie(summary.value.statusDistribution)), communityOption = computed(() => ({ tooltip: { trigger: 'axis' }, xAxis: { type: 'category', data: (summary.value.communityDistribution || []).map(x => x.label), axisLabel: { rotate: 24 } }, yAxis: { type: 'value' }, series: [{ type: 'bar', data: (summary.value.communityDistribution || []).map(x => x.value), itemStyle: { color: '#167d72' } }] }))
async function load() { loading.value = true; try { const [page, nextSummary] = await Promise.all([getRentals(query), getRentalSummary(year.value)]); rows.value = page.records; total.value = page.total; summary.value = nextSummary } catch (e) { ElMessage.error(apiMessage(e, '挂牌数据加载失败')) } finally { loading.value = false } }
async function open(row) { try { detail.value = await getRentalDetail(row.rentalListingId); drawer.value = true } catch (e) { ElMessage.error(apiMessage(e)) } }
function reset() { Object.assign(query, { communityId: null, agencyId: null, status: '', listingMode: '', layoutType: '', keyword: '', rentMin: null, rentMax: null, page: 1 }); load() }
function onPageChange(){load()}
onMounted(async () => { try { [communities.value, agencies.value, layouts.value] = await Promise.all([getCommunities(), getRentalAgencies(), getLayoutTemplates()]) } catch (e) { ElMessage.error(apiMessage(e)) }; load() })
</script>
<template><section v-loading="loading"><div class="kpis"><article v-for="[label, value] in cards" :key="label" class="panel"><span>{{ label }}</span><b>{{ value || 0 }}</b></article></div><el-tabs v-model="activeTab" class="panel tabs"><el-tab-pane label="挂牌列表" name="list"><section class="page"><div class="filters"><el-input v-model="query.keyword" clearable placeholder="小区、楼栋、房号或标题" @keyup.enter="query.page = 1; load()"/><el-select v-model="query.communityId" clearable placeholder="全部小区"><el-option v-for="c in communities" :key="c.communityId" :label="c.communityName" :value="c.communityId"/></el-select><el-select v-model="query.status" clearable placeholder="挂牌状态"><el-option v-for="(label, key) in statusLabels" :key="key" :label="label" :value="key"/></el-select><el-select v-model="query.listingMode" clearable placeholder="挂牌来源"><el-option v-for="(label, key) in modeLabels" :key="key" :label="label" :value="key"/></el-select><el-select v-model="query.layoutType" clearable placeholder="全部户型"><el-option v-for="item in layouts" :key="item.layoutType" :label="item.layoutName" :value="item.layoutType"/></el-select><el-select v-model="query.agencyId" clearable placeholder="全部中介"><el-option v-for="a in agencies" :key="a.agencyId" :label="a.agencyName" :value="a.agencyId"/></el-select><el-input-number v-model="query.rentMin" :min="0" controls-position="right" placeholder="最低租金"/><el-input-number v-model="query.rentMax" :min="0" controls-position="right" placeholder="最高租金"/><el-button type="primary" @click="query.page = 1; load()">查询</el-button><el-button @click="reset">重置</el-button></div><el-table :data="rows" height="calc(100vh - 400px)" @row-click="open"><el-table-column prop="communityName" label="小区"/><el-table-column prop="fullLocation" label="完整房产位置" min-width="235"/><el-table-column label="户型"><template #default="{row}">{{ layoutName(row) }}</template></el-table-column><el-table-column label="面积"><template #default="{ row }">{{ row.grossArea || '未填' }}{{ row.grossArea ? '㎡' : '' }}</template></el-table-column><el-table-column label="来源"><template #default="{ row }"><el-tag>{{ modeLabels[row.listingMode] || row.listingMode }}</el-tag></template></el-table-column><el-table-column prop="agencyName" label="中介"><template #default="{ row }">{{ row.agencyName || '—' }}</template></el-table-column><el-table-column label="月租"><template #default="{ row }">¥ {{ money(row.monthlyRent) }}</template></el-table-column><el-table-column prop="publishedAt" label="挂牌时间" min-width="165"/><el-table-column label="状态"><template #default="{ row }"><el-tag :type="row.status === 'PUBLISHED' ? 'success' : row.status === 'RENTED' ? 'primary' : 'info'">{{ statusLabels[row.status] || row.status }}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{ row }"><el-button link type="primary" @click.stop="open(row)">详情</el-button></template></el-table-column></el-table><PaginationBar v-model:page="query.page" v-model:page-size="query.pageSize" :total="total" @change="onPageChange"/></section></el-tab-pane><el-tab-pane label="数据分析" name="analysis"><div class="charts"><section class="chart"><h2>挂牌方式</h2><EChart :option="modeOption"/></section><section class="chart"><h2>挂牌状态</h2><EChart :option="statusOption"/></section><section class="chart"><h2>各小区挂牌量</h2><EChart :option="communityOption"/></section></div></el-tab-pane></el-tabs><el-drawer v-model="drawer" size="580px" title="挂牌详情"><template v-if="detail"><el-descriptions :column="1" border><el-descriptions-item label="完整房产位置">{{ detail.fullLocation }}</el-descriptions-item><el-descriptions-item label="户型 / 面积">{{ layoutName(detail) }} / {{ detail.grossArea || '未填' }}{{ detail.grossArea ? '㎡' : '' }}</el-descriptions-item><el-descriptions-item label="产权人">{{ detail.maskedOwnerName }}</el-descriptions-item><el-descriptions-item label="挂牌模式">{{ modeLabels[detail.listingMode] || detail.listingMode }}</el-descriptions-item><el-descriptions-item label="中介">{{ detail.agencyName || '—' }}</el-descriptions-item><el-descriptions-item label="授权状态">{{ detail.authorizationStatus || '—' }}</el-descriptions-item><el-descriptions-item label="月租 / 押金">¥ {{ money(detail.monthlyRent) }} / ¥ {{ money(detail.depositAmount) }}</el-descriptions-item><el-descriptions-item label="可入住日期">{{ detail.availableFrom }}</el-descriptions-item><el-descriptions-item label="挂牌时间">{{ detail.publishedAt || '—' }}</el-descriptions-item><el-descriptions-item label="关闭时间">{{ detail.closedAt || '—' }}</el-descriptions-item><el-descriptions-item label="状态">{{ statusLabels[detail.status] || detail.status }}</el-descriptions-item></el-descriptions><h3>挂牌标题</h3><p>{{ detail.listingTitle }}</p><h3>房源描述</h3><p class="description">{{ detail.description || '未填写' }}</p></template></el-drawer></section></template>
<style scoped>.kpis{display:grid;grid-template-columns:repeat(6,1fr);gap:14px;margin-bottom:17px}.kpis article,.chart,.page{padding:18px}.kpis span{display:block;color:#718692;font-size:12px}.kpis b{display:block;margin-top:10px;color:#14394a;font-size:20px}.charts{display:grid;grid-template-columns:repeat(3,1fr);gap:17px;margin-bottom:17px}.chart h2{margin:0 0 10px;font-size:16px}.filters{display:grid;grid-template-columns:1.4fr repeat(5,1fr) 120px 120px auto auto;gap:10px;margin-bottom:16px}.pager{display:flex;justify-content:space-between;align-items:center;margin-top:16px;color:#718692;font-size:12px}.description{white-space:pre-line;color:#536f78;line-height:1.7}@media(max-width:1450px){.kpis{grid-template-columns:repeat(3,1fr)}.charts{grid-template-columns:1fr}.filters{grid-template-columns:repeat(3,1fr) auto auto}}</style>
